    id integer NOT NULL,
    transform_id integer,
    run_method character varying(255) NOT NULL,
    status character varying(50) NOT NULL,
    is_active boolean,
    start_time timestamp with time zone DEFAULT now() NOT NULL,
    end_time timestamp with time zone,
    message text,
    user_id integer,
    transform_name character varying(254),
    transform_entity_id character(21),
    checkpoint_filter_field_id integer,
    checkpoint_lo_value text,
    checkpoint_hi_value text,
    metered_as character varying(50)
);


--
-- Name: TABLE transform_run; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.transform_run IS 'Table to track transform executions and their status in the app database';


