    owner_user_id
   FROM public.metabase_table;


--
-- Name: v_task_runs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_task_runs AS
 SELECT id,
    run_type,
    entity_type,
    entity_id,
        CASE
            WHEN ((entity_type)::text = 'database'::text) THEN ('database_'::text || entity_id)
            WHEN ((entity_type)::text = 'card'::text) THEN ('card_'::text || entity_id)
            WHEN ((entity_type)::text = 'dashboard'::text) THEN ('dashboard_'::text || entity_id)
            ELSE (((entity_type)::text || '_'::text) || entity_id)
        END AS entity_qualified_id,
    started_at,
    ended_at,
        CASE
            WHEN (ended_at IS NOT NULL) THEN (EXTRACT(epoch FROM (ended_at - started_at)))::double precision
            ELSE NULL::double precision
        END AS duration_seconds,
    status,
    process_uuid,
    updated_at
   FROM public.task_run;


--
-- Name: v_tasks; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_tasks AS
 SELECT id,
    task,
    status,
    ('database_'::text || db_id) AS database_qualified_id,
    started_at,
    ended_at,
    ((duration)::double precision / (1000)::double precision) AS duration_seconds,
    task_details AS details,
    run_id
   FROM public.task_history;


